void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // =============
    // Configuration
    // =============

    // Two colors to blend between
    vec3 color1 = vec3(1.0, 0.0, 0.0);
    vec3 color2 = vec3(0.7, 0.04, 0.5);

    // Background color
    vec3 colorBackground = vec3(0.0, 0.0, 0.0);

    // Threshold for motion detection
    float threshold = 0.2;

    // How much trippy wobble to use in the motion detection
    float wobble = 0.4;

    // How many bands to use in color banding
    int colorBands = 4;

    // =====
    // Logic
    // =====

    vec2 uv = fragCoord.xy / iResolution.xy;

    // Texture output from the trippy texture generator (Buffer D)
    vec4 trippyTex = texture(iChannel2, uv);

    // Brightness of the trippy texture
    float gray = (trippyTex.r + (trippyTex.g + (trippyTex.b))) * 0.333;

    // Generate base colors
    vec3 color = vec3(1.0);
    color = (color1 * (1.0 - gray)) + (color2 * gray);
    color = color * 0.75 + 0.25;
    vec4 baseColor = vec4(color, 1.0);

    vec4 currentFrame = texture(iChannel0, uv); // Webcam input
    vec4 delayedFrame = texture(iChannel1, uv); // Delayed frame from previous buffer

    // Calculate the difference between the current and delayed frames
    vec4 diff1 = abs(currentFrame - delayedFrame);
    vec4 diff2 = abs(currentFrame - trippyTex);
    vec4 diff = (diff1 * (1.0 - wobble)) + (diff2 * wobble);

    // Determine if there is enough motion to display this pixel
    bool motion = (diff.r + diff.g + diff.b) > threshold ? true : false;

    // Apply shading, banding color in four brightnesses
    float br = 1.0 - ((currentFrame.r + currentFrame.g + currentFrame.b) / 3.0);
    br = floor(br * float(colorBands)) / float(colorBands);
    vec4 shadedColor = baseColor * br;

    // Apply the motion mask to the shaded color
    fragColor = motion ? shadedColor : vec4(colorBackground, 1.0);
}

// Buffer A (Captures the current frame and averages with previous frame)
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord / iResolution.xy;
    vec4 currentFrame = texture(iChannel0, uv);
    vec4 previousFrame = texture(iChannel1, uv); // Assuming this buffer's output is fed back into itself

    // Blend the current frame with the previous frame to reduce noise
    float blendFactor = 0.1;  // Adjust this factor to control smoothing
    fragColor = mix(previousFrame, currentFrame, blendFactor);
}

