// Buffer A (Captures the current frame with controlled timing)
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord / iResolution.xy;
    vec4 currentFrame = texture(iChannel0, uv);

    // Only update this buffer every UPDATE_INTERVAL seconds
    if (mod(iTime, UPDATE_INTERVAL) < 0.016) { // Assuming 60 FPS, so each frame lasts approximately 0.016 seconds
        fragColor = currentFrame;
    } else {
        fragColor = texture(iChannel1, uv); // Hold previous value by sampling itself
    }
}

