void mainImage(out vec4 fragColor, in vec2 fragCoord) {
   	vec2 uv = fragCoord.xy / iResolution.xy;

    vec4 tex = texture(iChannel0, uv);

    vec3 color = tex.rgb;
    if(tex.a < 1.0) {
        color = texture(iChannel1, uv).rgb;
    }
    else {
        vec2 offset = (tex.xy * 2.0 - 1.0);
        float d = 20.0;
        offset.x = cos(offset.x * d);
        offset.y = sin(offset.y * d);
        vec2 tex_coord = fract(uv + offset * 0.01);

       	color = texture(iChannel0, tex_coord).rgb;

        float gray = (color.r + color.g + color.b) * 0.333;
        float v = sin(iTime * 2.0 + gray * 20.0) * 0.5 + 0.5;
        if(v < 0.3) {
       		color = texture(iChannel1, uv).rgb;
        }
    }

    fragColor = vec4(color, 1.0);
}
